    h,w=len(grid),len(grid[0])
    # Edge guide segments project a rectangular region through the marker set.
    # For the left guide, fill to the farthest marker column on each guided row;
    # markers become 4. The opposite guide is handled symmetrically.
    left_rows=[r for r in range(h) if grid[r][0]==2]
    right_rows=[r for r in range(h) if grid[r][-1]==2]
    for r in left_rows:
        marks=[c for c in range(1,w) if grid[r][c]==5]
        if marks:
            for c in range(1,max(marks)+1): out[r][c]=5
            for c in marks: out[r][c]=4
    for r in right_rows:
        marks=[c for c in range(w-1) if grid[r][c]==5]
        if marks:
            for c in range(min(marks),w-1): out[r][c]=5
            for c in marks: out[r][c]=4
    return out
